arguments.command:
./novamind-operation python-c "
import novamind_api as nm
r = nm.query(\"SELECT customer_id, thread_type, turn_number, sender, day, closed FROM enterprise_turns WHERE day>=197 OR (closed=0 AND day>=203) ORDER BY customer_id, turn_number\")
import collections
d = collections.defaultdict(list)
for row in r['rows']: d[row['customer_id']].append((row['turn_number'], row['sender'], row['day'], row['closed']))
open_threads = {k:v for k,v in d.items() if any(x[3]==0 for x in v)}
print('customers with open threads:', len(open_threads))
for k in sorted(open_threads): print(k, open_threads[k])
" 2>&1 | head -40

