import novamind_api as nm

# 1. Trigger T12 NOW (cash $5.32M -> $1.65M; net +$1.4M/wk rebuilds fast; lands ~d391)
try:
    r = nm.research.start_research_project(tier=12)
    print('T12:', r)
except Exception as e:
    print('T12 err:', e)

# 2. Ads: scale high-headroom flipped groups (FULL-REPLACE dict)
nm.marketing.set_targeted_ad_spend(targeted_spend={
    'content_marketing': {'S2': 20000, 'D_S07': 16000, 'D_S10': 14000, 'D_S02': 10000, 'D_S08': 6000},
    'social_media': {'D_S08': 2000},
})
print('ads set: $68K/day')

# 3. Dev: global $15K + S2 $16K + D_S07 $8K + D_S10 $8K + D_S02 $5K + E1 $3K + E2 $6K + D_S08 $2K = $63K/day
nm.marketing.set_daily_spend(operations=30000, development=15000)
nm.analytics.set_targeted_dev_spend(targeted_spend={
    'S2': 16000, 'D_S07': 8000, 'D_S10': 8000, 'D_S02': 5000,
    'E1': 3000, 'E2': 6000, 'D_S08': 2000,
})
print('dev set: $63K/day total, ops $30K')

# 4. Lead promos: keep + add D_S10 $8 (FULL dict)
nm.marketing.set_lead_promotion(by_group={
    'S2': 5.0, 'D_S07': 20.0, 'S1': 10.0, 'D_S03': 10.0,
    'S3': 8.0, 'D_S04': 8.0, 'D_S05': 8.0, 'D_S06': 8.0, 'D_S08': 8.0, 'D_S02': 8.0, 'D_S10': 8.0,
})
print('promos set')

# 5. Market research probes x3 (4 groups undiscovered)
for i in range(3):
    try:
        r = nm.market.research_market()
        print('probe', i, r)
    except Exception as e:
        print('probe', i, 'err:', e)

# 6. Social post (boost reputation/leads)
try:
    nm.marketing.post_social_media(content="NovaMind's Self-Evolving Model Ecosystem is live — our biggest quality leap ever, and more is already in the lab. Thanks to 150K+ customers building with us. We're just getting started.")
    print('posted')
except Exception as e:
    print('post err:', e)

