# WK51 DIAGNOSTIC: single-rung offers at varied price points.
# Hypothesis test: is enterprise rejection price-bound or quality/reputation-bound?
# If C@$2 (near-zero price, max quality plan) gets rejected -> quality_perceived ~ 0 (reputation/hidden factor).
# If C@$2 accepted but higher prices rejected -> steep curve, find ceiling.
import novamind_api as nm

WTP = {'E1': 33.2, 'E2': 88.4, 'E3': 104.0, 'D_E01': 147.0, 'D_E02': 82.0,
       'D_E03': 213.0, 'D_E04': 180.0, 'D_E05': 131.0, 'D_E06': 90.0,
       'D_E07': 196.0, 'D_E08': 164.0, 'D_E09': 106.0, 'D_E10': 53.0}

rows = nm.query(
    "SELECT t.customer_id, t.sender, t.day, t.turn_number, c.group_id "
    "FROM enterprise_turns t JOIN customers c ON c.customer_id = t.customer_id "
    "WHERE t.closed = 0")['rows']
latest = {}
for r in rows:
    cid = r['customer_id']
    key = (r['day'], r['turn_number'])
    if cid not in latest or key > latest[cid][0]:
        latest[cid] = (key, r)

# group pending leads (latest sender NOT agent)
by_group = {}
for cid, (key, r) in latest.items():
    if r['sender'] == 'agent':
        continue
    by_group.setdefault(r['group_id'], []).append(cid)

deals = []
assignment = []
for g, cids in sorted(by_group.items()):
    wtp = WTP.get(g, 100.0)
    cids = sorted(cids)
    for i, cid in enumerate(cids):
        rung = i % 4
        if rung == 0:
            offer = [['C', 2.0]]                      # ultra-cheap, max quality plan
        elif rung == 1:
            offer = [['C', round(0.40 * wtp, 2)]]     # mid price
        elif rung == 2:
            offer = [['C', round(0.75 * wtp, 2)]]     # near-WTP
        else:
            offer = [['A', 1.0]]                      # ultra-cheap low tier probe
        deals.append([cid, offer])
        assignment.append((cid, g, offer))

if deals:
    res = nm.enterprise.send_enterprise_deal(deals=deals)
    ok = sum(1 for x in res.get('results', []) if x.get('success'))
    print('sent %d/%d deals' % (ok, len(deals)))
for a in assignment:
    print(a)

