./novamind-operation python-c "
import novamind_api as nm
r = nm.query(\"SELECT amount, COUNT(*) as n FROM ledger WHERE category='subscription_payment' AND day>=470 AND day<=476 GROUP BY amount ORDER BY n DESC\")
for row in r['rows']: print(row)
print('---current subs by plan and billing_mod---')
r = nm.query(\"SELECT plan, billing_day_mod30 as m, COUNT(*) as n FROM subscriptions WHERE status='subscribed' GROUP BY plan, m ORDER BY m\")
tot={}
for row in r['rows']:
    tot.setdefault(row['m'],{'B':0,'C':0,'A':0})
    tot[row['m']][row['plan']]=row['n']
for m in sorted(tot): print(m, tot[m])
"

